ge":"RAIN 4K","publishedAt":"2025-05-24T13:01:20Z","admission":{"version":1,"status":"accepted","uniqueEvidenceCount":8,"evidence":[{"title":"Trailer","startSeconds":0},{"title":"SS1","startSeconds":64},{"title":"SS2","startSeconds":540},{"title":"Enter Town","startSeconds":1050},{"title":"SS3","startSeconds":1130},{"title":"SS4 - Downhill","startSeconds":1990},{"title":"SS4 - Uphill","startSeconds":2481},{"title":"SS3 - Return","startSeconds":2985}]}}',
